.darma-loader-tw-image-placeholder { position: relative; overflow: hidden; width: var(--loader-size, 200px); height: calc(var(--loader-size, 200px) * .68); border-radius: calc(var(--loader-size, 200px) * .05); background: color-mix(in srgb, var(--loader-color, #94a3b8) 12%, transparent); border: calc(var(--loader-size, 200px) * .01) solid color-mix(in srgb, var(--loader-color, #94a3b8) 28%, transparent); box-sizing: border-box; }
.darma-loader-tw-image-placeholder .darma-loader-tw-image-placeholder__sun { position: absolute; left: 16%; top: 18%; width: calc(var(--loader-size, 200px) * .1); height: calc(var(--loader-size, 200px) * .1); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #94a3b8) 55%, transparent); }
.darma-loader-tw-image-placeholder .darma-loader-tw-image-placeholder__hill { position: absolute; left: 20%; bottom: 16%; width: 0; height: 0; border-left: calc(var(--loader-size, 200px) * .14) solid transparent; border-right: calc(var(--loader-size, 200px) * .14) solid transparent; border-bottom: calc(var(--loader-size, 200px) * .2) solid color-mix(in srgb, var(--loader-color, #94a3b8) 48%, transparent); }
.darma-loader-tw-image-placeholder .darma-loader-tw-image-placeholder__hill::after { content: ''; position: absolute; left: calc(var(--loader-size, 200px) * .04); bottom: calc(var(--loader-size, 200px) * -.2); border-left: calc(var(--loader-size, 200px) * .19) solid transparent; border-right: calc(var(--loader-size, 200px) * .19) solid transparent; border-bottom: calc(var(--loader-size, 200px) * .27) solid color-mix(in srgb, var(--loader-color, #94a3b8) 34%, transparent); }
.darma-loader-tw-image-placeholder .darma-loader-tw-image-placeholder__glow { position: absolute; top: 0; bottom: 0; left: 0; right: 0; background: linear-gradient(100deg, transparent 35%, color-mix(in srgb, var(--loader-color, #94a3b8) 40%, transparent) 50%, transparent 65%); animation: darma-loader-tw-image-placeholder-twGlow calc(var(--loader-speed, 1s) * 1.7) linear infinite; }
@keyframes darma-loader-tw-image-placeholder-twGlow { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }

